// Verifies the request from Fanout before anything is sent (spec §5.9):
//   X-Signature: sha256=<hex HMAC-SHA256 of "<X-Timestamp>.<raw body>">
// keyed with N8N_SHARED_SECRET. Constant-time compare, 5-minute replay window.
// Throwing here makes the webhook answer 500, which Fanout records as a failure.
const crypto = require('crypto');

const secret = $env.N8N_SHARED_SECRET;
if (!secret || secret.length < 16) {
  throw new Error('N8N_SHARED_SECRET is not set (at least 16 characters).');
}

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-timestamp'] || '');
const signature = String(headers['x-signature'] || '');

// The signature covers the raw bytes. The Webhook node keeps them as binary
// data ("Raw Body" option). Fanout builds the body with JSON.stringify, so
// re-serialising the parsed body gives the same bytes if the raw copy is missing.
let raw;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (error) {
  raw = JSON.stringify(item.json.body);
}

const expected =
  'sha256=' +
  crypto.createHmac('sha256', secret).update(timestamp + '.' + raw, 'utf8').digest('hex');
const given = Buffer.from(signature, 'utf8');
const wanted = Buffer.from(expected, 'utf8');
if (given.length !== wanted.length || !crypto.timingSafeEqual(given, wanted)) {
  throw new Error('Invalid signature.');
}

const age = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (!/^\d{1,12}$/.test(timestamp) || age > 300) {
  throw new Error('Stale request.');
}

const payload = JSON.parse(raw);
if (payload.version !== 1 || payload.kind !== 'discord') {
  throw new Error('Unexpected payload.');
}
const discord = payload.discord || {};
// Defence in depth: only ever post to a Discord webhook, whatever was signed.
const pattern = /^https:\/\/discord\.com\/api\/webhooks\/[0-9]{5,30}\/[A-Za-z0-9_-]{20,200}$/;
if (typeof discord.webhookUrl !== 'string' || !pattern.test(discord.webhookUrl)) {
  throw new Error('Unexpected payload.');
}
if (!Array.isArray(discord.messages) || discord.messages.length === 0 || discord.messages.length > 10) {
  throw new Error('Unexpected payload.');
}

return [{ json: payload }];

// One item per Discord message; the next node posts them one at a time, in order.
const job = $input.first().json;
return job.discord.messages.map((content, index) => ({
  json: { webhookUrl: job.discord.webhookUrl, content: String(content), index },
}));

// Reports the outcome to Fanout, signed the same way as the request that came in.
// Only ids, a yes/no and an HTTP status travel back — never the message or the URL.
const crypto = require('crypto');

const secret = $env.N8N_SHARED_SECRET;
const appUrl = String($env.FANOUT_APP_URL || '').replace(/\/+$/, '');
if (!secret || !appUrl) {
  throw new Error('N8N_SHARED_SECRET and FANOUT_APP_URL must be set.');
}

const job = $('Verify signature').first().json;

// A delivery node that failed continues with an `error` field instead of stopping.
const failed = $input.all().find((entry) => entry.json && entry.json.error);
const result = { jobId: job.jobId, attemptId: job.attemptId, ok: !failed };
if (failed) {
  result.error = 'delivery_failed';
  const error = failed.json.error || {};
  const status = Number(error.httpCode || error.status || error.statusCode);
  if (Number.isInteger(status) && status >= 100 && status <= 599) {
    result.httpStatus = status;
  }
}

const body = JSON.stringify(result);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature =
  'sha256=' +
  crypto.createHmac('sha256', secret).update(timestamp + '.' + body, 'utf8').digest('hex');

return [{ json: { url: appUrl + '/api/publish/callback', body, timestamp, signature } }];
